/**
 * empresa.jsx — EMPRESA SELECCIONADA en toda la app (24/09/2026).
 *
 * Alsocasals / Ferros / Quimlab. La elección se guarda en el navegador
 * y viaja en CADA llamada al backend como cabecera «X-Empresa» (lo hace
 * instalarEmpresaEnFetch, llamado desde main.jsx). Sin elección, o con
 * ALSO CASALS, todo funciona exactamente como antes.
 * Al cambiar de empresa se recarga la página para que todas las
 * pantallas carguen los datos de la nueva empresa (y no se mezclen).
 */
import React, { useEffect, useState } from "react";

const LS_EMPRESA_APP = "agente_ventas_empresa_v1";

// MODO ADMINISTRADOR (24/09/2026): herramientas técnicas (p.ej. «Diagnóstico»)
// ocultas para el uso normal. Se activa abriendo la app con ?admin=1 en la
// dirección (http://localhost:5173/?admin=1) y se desactiva con ?admin=0.
// Queda recordado en este navegador.
const LS_ADMIN = "agente_ventas_admin_v1";
try {
  const p = new URLSearchParams(window.location.search).get("admin");
  if (p === "1") localStorage.setItem(LS_ADMIN, "1");
  if (p === "0") localStorage.removeItem(LS_ADMIN);
} catch {}
export function esAdmin() {
  try { return localStorage.getItem(LS_ADMIN) === "1"; } catch { return false; }
}

export function empresaGuardada() {
  try { return JSON.parse(localStorage.getItem(LS_EMPRESA_APP) || "null"); } catch { return null; }
}
/** true si la empresa elegida NO es la de por defecto (ALSO CASALS) */
export function esOtraEmpresa() {
  const e = empresaGuardada();
  return !!(e && e.id && !e.porDefecto);
}

/** Añade la cabecera X-Empresa a todas las llamadas a /api del navegador. */
export function instalarEmpresaEnFetch() {
  if (window.__empresaFetchInstalado) return;
  window.__empresaFetchInstalado = true;
  const original = window.fetch.bind(window);
  window.fetch = (entrada, opciones = {}) => {
    try {
      const url = typeof entrada === "string" ? entrada : entrada?.url || "";
      const e = empresaGuardada();
      if (e?.id && !e.porDefecto && (url.startsWith("/api") || url.includes(`${location.host}/api`))) {
        const cabeceras = new Headers(opciones.headers || (typeof entrada !== "string" ? entrada.headers : undefined) || {});
        if (!cabeceras.has("X-Empresa")) cabeceras.set("X-Empresa", e.id);
        return original(entrada, { ...opciones, headers: cabeceras });
      }
    } catch {}
    return original(entrada, opciones);
  };
}

// Logos de las empresas (recortados de las plantillas oficiales de borrador)
const LOGO_ALSO = "data:image/png;base64,";
const LOGO_QUIMLAB = "data:image/png;base64,";
const LOGO_FERROS = "data:image/png;base64,";
const estilo = (nombre) => {
  const n = String(nombre || "").toLowerCase();
  if (n.includes("quimlab")) return { logo: LOGO_QUIMLAB, inicial: "QUIMLAB", color: "text-emerald-700" };
  if (n.includes("ferros")) return { logo: LOGO_FERROS, inicial: "fCA", color: "text-slate-700" };
  return { logo: LOGO_ALSO, inicial: "AC", color: "text-blue-700" };
};

export function SelectorEmpresa() {
  const [empresas, setEmpresas] = useState([]);
  const [error, setError] = useState(null);
  const [cargando, setCargando] = useState(true);
  const actual = empresaGuardada();

  const esNoUsar = (e) => /no\s*usar/i.test(`${e?.nombre || ""} ${e?.displayName || ""}`);

  const cargar = (refrescar = false) => {
    setCargando(true);
    setError(null);
    fetch(`/api/empresas-app${refrescar ? "?refrescar=1" : ""}`)
      .then((r) => r.json())
      .then((d) => {
        const crudas = d.empresas || [];
        // Las marcadas "(no usar)" en BC no se ofrecen para trabajar
        const lista = crudas.filter((e) => !esNoUsar(e));
        const ocultas = crudas.length - lista.length;
        setEmpresas(lista.length ? lista : crudas); // si todas son "no usar", mostrarlas igual
        if (d.aviso) setError(`No se pudo leer la lista completa de BC: ${d.aviso}`);
        else if (ocultas > 0) setError(null);

        const g = empresaGuardada();
        // Si no hay empresa, o la guardada ya no existe, o es una de
        // "no usar" → saltar a la de por defecto (ALSO CASALS).
        const guardadaInvalida =
          !g ||
          !lista.some((e) => e.id === g.id) ||
          esNoUsar(g);
        if (guardadaInvalida && lista.length) {
          const def = lista.find((e) => e.porDefecto) || lista[0];
          if (def && def.id !== g?.id) {
            try { localStorage.setItem(LS_EMPRESA_APP, JSON.stringify(def)); } catch {}
            window.location.reload();
            return;
          }
          if (def && !g) {
            try { localStorage.setItem(LS_EMPRESA_APP, JSON.stringify(def)); } catch {}
          }
        }
        if (!lista.length && crudas.length) {
          setError("Solo hay empresas marcadas «no usar» en BC. Revisa los nombres en Business Central.");
        }
      })
      .catch(() => setError("Backend no disponible — no se pueden listar empresas"))
      .finally(() => setCargando(false));
  };

  useEffect(() => { cargar(false); }, []);

  const elegir = (e) => {
    if (actual?.id === e.id) return;
    try { localStorage.setItem(LS_EMPRESA_APP, JSON.stringify(e)); } catch {}
    window.location.reload(); // todas las pantallas recargan con los datos de la nueva empresa
  };

  const idActual = actual?.id || empresas.find((e) => e.porDefecto)?.id;
  return (
    <div>
      <div className="flex items-center justify-between mb-1.5 px-0.5">
        <div className="text-[10px] tracking-wider text-slate-500 font-semibold">EMPRESA</div>
        <button
          type="button"
          onClick={() => cargar(true)}
          disabled={cargando}
          title="Volver a leer las empresas desde Business Central"
          className="text-[10px] text-blue-600 hover:underline disabled:opacity-50"
        >
          {cargando ? "…" : "↻"}
        </button>
      </div>
      {actual && (
        <div className="text-[10px] text-slate-600 mb-1.5 px-0.5 truncate" title={actual.displayName || actual.nombre}>
          Activa: <span className="font-semibold">{actual.displayName || actual.nombre}</span>
        </div>
      )}
      <div className="space-y-1.5">
        {empresas.map((e) => {
          const st = estilo(e.nombre);
          const activa = e.id === idActual;
          return (
            <button
              key={e.id}
              onClick={() => elegir(e)}
              title={`${e.displayName || e.nombre}${e.cif ? ` · CIF ${e.cif}` : ""}`}
              className={`w-full flex flex-col items-center justify-center gap-0.5 rounded px-2 py-1.5 bg-white border transition-all ${
                activa
                  ? "border-blue-500 ring-1 ring-blue-500 shadow-sm"
                  : "border-slate-200 opacity-70 hover:opacity-100 hover:border-slate-400"
              }`}
            >
              {st.logo ? (
                <img src={st.logo} alt={e.displayName || e.nombre} className="max-h-6 max-w-full object-contain" />
              ) : (
                <span className={`font-extrabold tracking-wider text-[13px] ${st.color}`}>{st.inicial}</span>
              )}
              <span className="text-[9px] text-slate-500 leading-tight truncate max-w-full">
                {e.displayName || e.nombre}
              </span>
            </button>
          );
        })}
        {!cargando && empresas.length === 0 && (
          <div className="text-[10px] text-amber-700 px-0.5">Ninguna empresa disponible</div>
        )}
      </div>
      {error && <div className="text-[10px] text-amber-600 mt-1 leading-snug">{error}</div>}
    </div>
  );
}
